effects.css:
.btn {
  position: relative;
  padding: 12px 32px;
  border: none;
  border-radius: 8px;
  background: #1f2328;
  color: #fff;
  font-size: 16px;
  cursor: pointer;
  z-index: 0;
}
.btn::before {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 10px;
  background: linear-gradient(90deg, #ff6b6b, #feca57, #48dbfb, #ff9ff3, #ff6b6b);
  background-size: 400%;
  z-index: -1;
  opacity: 0;
  transition: opacity .3s;
  animation: flow 3s linear infinite;
}
.btn:hover::before { opacity: 1; }
@keyframes flow {
  to { background-position: 400% 0; }
}

.btn {
  padding: 12px 32px;
  border: 2px solid #2563eb;
  border-radius: 8px;
  background: transparent;
  color: #2563eb;
  font-size: 16px;
  cursor: pointer;
  background-image: linear-gradient(#2563eb, #2563eb);
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 0% 100%;
  transition: background-size .35s, color .35s;
}
.btn:hover {
  background-size: 100% 100%;
  color: #fff;
}

.btn {
  padding: 12px 32px;
  border: none;
  border-radius: 999px;
  background: #e11d48;
  color: #fff;
  font-size: 16px;
  cursor: pointer;
  animation: pulse 1.8s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(225, 29, 72, .5); }
  70% { box-shadow: 0 0 0 16px rgba(225, 29, 72, 0); }
  100% { box-shadow: 0 0 0 0 rgba(225, 29, 72, 0); }
}

.btn {
  padding: 12px 32px;
  border: none;
  border-radius: 10px;
  background: #0e9f6e;
  color: #fff;
  font-size: 16px;
  cursor: pointer;
  box-shadow: 0 6px 0 #066048;
  transition: all .1s;
}
.btn:active {
  transform: translateY(6px);
  box-shadow: 0 0 0 #066048;
}

.btn {
  position: relative;
  padding: 8px 4px;
  border: none;
  background: none;
  color: #1f2328;
  font-size: 16px;
  cursor: pointer;
}
.btn::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  background: #7c3aed;
  transform: scaleX(0);
  transform-origin: right;
  transition: transform .3s;
}
.btn:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.loader {
  width: 48px;
  height: 48px;
  border: 5px solid #e3e6ea;
  border-top-color: #2563eb;
  border-radius: 50%;
  animation: spin .8s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.dots { display: flex; gap: 8px; }
.dots span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #2563eb;
  animation: bounce 1.2s infinite ease-in-out;
}
.dots span:nth-child(2) { animation-delay: .15s; }
.dots span:nth-child(3) { animation-delay: .3s; }
@keyframes bounce {
  0%, 80%, 100% { transform: scale(.6); opacity: .4; }
  40% { transform: scale(1); opacity: 1; }
}

.skeleton { width: 220px; display: grid; gap: 12px; }
.line {
  height: 16px;
  border-radius: 6px;
  background: linear-gradient(90deg, #eee 25%, #f7f7f7 50%, #eee 75%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite;
}
@keyframes shimmer {
  to { background-position: -200% 0; }
}

.dual {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: #e11d48;
  border-bottom-color: #e11d48;
  animation: spin 1s linear infinite;
  position: relative;
}
.dual::after {
  content: '';
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-left-color: #f59e0b;
  border-right-color: #f59e0b;
  animation: spin .6s linear infinite reverse;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.bar {
  width: 240px;
  height: 14px;
  background: #e3e6ea;
  border-radius: 999px;
  overflow: hidden;
}
.fill {
  height: 100%;
  width: 60%;
  border-radius: 999px;
  background: repeating-linear-gradient(
    45deg, #0e9f6e 0 12px, #12b981 12px 24px);
  background-size: 34px 100%;
  animation: slide 1s linear infinite;
}
@keyframes slide {
  to { background-position: 34px 0; }
}

.card {
  width: 220px;
  padding: 20px;
  background: #fff;
  border-radius: 14px;
  border: 1px solid #e3e6ea;
  font-family: sans-serif;
  transition: transform .25s, box-shadow .25s;
}
.card:hover {
  transform: translateY(-8px);
  box-shadow: 0 16px 32px rgba(31, 35, 40, .12);
}

.card {
  position: relative;
  width: 240px;
  height: 140px;
  border-radius: 12px;
  overflow: hidden;
}
.img {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #667eea, #764ba2);
  transition: transform .4s;
}
.card:hover .img { transform: scale(1.1); }
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(31, 35, 40, .55);
  color: #fff;
  font-family: sans-serif;
  opacity: 0;
  transition: opacity .3s;
}
.card:hover .overlay { opacity: 1; }

.bg {
  width: 260px;
  height: 150px;
  border-radius: 16px;
  background: linear-gradient(135deg, #f093fb, #f5576c, #4facfe);
  display: flex;
  align-items: center;
  justify-content: center;
}
.glass {
  padding: 20px 32px;
  border-radius: 14px;
  background: rgba(255, 255, 255, .2);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, .35);
  color: #fff;
  font-family: sans-serif;
  text-align: center;
}

.card {
  position: relative;
  width: 220px;
  padding: 24px;
  background: #fff;
  border-radius: 12px;
  font-family: sans-serif;
  overflow: hidden;
}
.card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 12px;
  padding: 2px;
  background: conic-gradient(from var(--a, 0deg), transparent 70%, #2563eb, transparent);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity .3s;
  animation: rotate 2s linear infinite;
}
.card:hover::before { opacity: 1; }
@property --a {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}
@keyframes rotate {
  to { --a: 360deg; }
}

.text {
  font-family: sans-serif;
  font-size: 42px;
  font-weight: 800;
  background: linear-gradient(90deg, #2563eb, #7c3aed, #e11d48);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.typing {
  font-family: monospace;
  font-size: 28px;
  width: 13ch;
  white-space: nowrap;
  overflow: hidden;
  border-right: 3px solid #1f2328;
  animation:
    typing 2.2s steps(13) forwards,
    caret .7s step-end infinite;
}
@keyframes typing {
  from { width: 0; }
}
@keyframes caret {
  50% { border-color: transparent; }
}

.outline {
  font-family: sans-serif;
  font-size: 52px;
  font-weight: 900;
  letter-spacing: 4px;
  color: transparent;
  -webkit-text-stroke: 2px #1f2328;
  transition: color .3s;
}
.outline:hover { color: #1f2328; }

.dark {
  background: #0b0b12;
  padding: 32px 48px;
  border-radius: 14px;
  display: inline-block;
}
.neon {
  font-family: sans-serif;
  font-size: 44px;
  color: #fff;
  letter-spacing: 6px;
  text-shadow:
    0 0 6px #0ff,
    0 0 18px #0ff,
    0 0 42px #0ff;
  animation: flicker 2.5s infinite alternate;
}
@keyframes flicker {
  0%, 100% { opacity: 1; }
  92% { opacity: 1; }
  93% { opacity: .4; }
  94% { opacity: 1; }
}

.wave {
  font-family: sans-serif;
  font-size: 52px;
  font-weight: 900;
  background:
    radial-gradient(circle at 50% 120%, #4facfe 38%, transparent 42%),
    radial-gradient(circle at 30% 130%, #00c6fb 30%, transparent 46%),
    #dbeafe;
  background-size: 200% 200%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: wave 3s ease-in-out infinite alternate;
}
@keyframes wave {
  to { background-position: 100% 40%; }
}

.dots-bg {
  width: 260px;
  height: 150px;
  border-radius: 14px;
  background-color: #fff;
  background-image: radial-gradient(#cbd5e1 1.5px, transparent 1.5px);
  background-size: 22px 22px;
}

.grid-bg {
  width: 260px;
  height: 150px;
  border-radius: 14px;
  background-color: #f8fafc;
  background-image:
    linear-gradient(#e2e8f0 1px, transparent 1px),
    linear-gradient(90deg, #e2e8f0 1px, transparent 1px);
  background-size: 24px 24px;
}

.gradient-bg {
  width: 260px;
  height: 150px;
  border-radius: 14px;
  background: linear-gradient(120deg, #a1c4fd, #c2e9fb, #fbc2eb, #a6c1ee);
  background-size: 300% 300%;
  animation: move 8s ease infinite;
}
@keyframes move {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.stripes {
  width: 260px;
  height: 48px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: monospace;
  font-weight: bold;
  color: #1f2328;
  background: repeating-linear-gradient(
    45deg, #fbbf24 0 16px, #1f2328 16px 32px);
  background-clip: padding-box;
  border: 6px solid transparent;
  background-color: #fde68a;
}

.spotlight {
  width: 260px;
  height: 150px;
  border-radius: 14px;
  background: #111827;
  color: #9ca3af;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: sans-serif;
  position: relative;
  overflow: hidden;
}
.spotlight::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(
    160px circle at var(--x, 50%) var(--y, 50%),
    rgba(99, 102, 241, .5), transparent 70%);
}
.spotlight > * { position: relative; }
